B.bch=new A.a("\u0648\u0642\u062f \u0630\u0643\u0631 \u0627\u0644\u0645\u0624\u0631\u062e\u0648\u0646 \u0623\u0646 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0623\u062a\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u0639\u0644\u0646\u0627\u064b \u0645\u0639\u0627\u0631\u0636\u062a\u0647 \u0644\u0647\u0630\u0647 \u0627\u0644\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0648\u0642\u0627\u0644 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u0644\u0633\u062a \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644: \u0628\u0644\u0649 \u0642\u0627\u0644: \u0623\u0648\u0644\u0633\u0646\u0627 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u061f \u0642\u0627\u0644: \u0628\u0644\u0649 \u0642\u0627\u0644: \u0623\u0648\u0644\u064a\u0633\u0648\u0627 \u0628\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0642\u0627\u0644: \u0641\u0639\u0644\u0627\u0645 \u0646\u064f\u0639\u0637\u064a \u0627\u0644\u062f\u0646\u064a\u0629 \u0641\u064a \u062f\u064a\u0646\u0646\u0627\u061f \u0642\u0627\u0644 \u0625\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0644\u0633\u062a \u0623\u0639\u0635\u064a\u0647\u060c \u0648\u0641\u064a \u0631\u0648\u0627\u064a\u0629: \u0623\u0646\u0627 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0644\u0646 \u0623\u062e\u0627\u0644\u0641 \u0623\u0645\u0631\u0647 \u0648\u0644\u0646 \u064a\u0636\u064a\u0639\u0646\u064a\u060c \u0642\u0644\u062a \u0623\u0648\u0644\u064a\u0633 \u0643\u0646\u062a \u062a\u062d\u062f\u062b\u0646\u0627 \u0623\u0646\u0627 \u0633\u0646\u0623\u062a\u064a \u0627\u0644\u0628\u064a\u062a \u0641\u0646\u0637\u0648\u0641 \u0628\u0647\u061f \u0642\u0627\u0644 \u0628\u0644\u0649\u060c \u0641\u0623\u062e\u0628\u0631\u062a\u0643 \u0623\u0646\u0627 \u0646\u0623\u062a\u064a\u0647 \u0627\u0644\u0639\u0627\u0645\u061f \u0642\u0644\u062a \u0644\u0627\u060c \u0642\u0627\u0644 \u0641\u0625\u0646\u0643 \u0622\u062a\u064a\u0647 \u0648\u0645\u0637\u0648\u0641 \u0628\u0647 \u0642\u0627\u0644 \u0639\u0645\u0631: \u0641\u0623\u062a\u064a\u062a \u0623\u0628\u0627 \u0628\u0643\u0631 \u0641\u0642\u0644\u062a \u0644\u0647: \u064a\u0627 \u0623\u0628\u0627 \u0628\u0643\u0631: \u0623\u0644\u064a\u0633 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0642\u0627\u0644: \u0623\u0648\u0644\u0633\u0646\u0627 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0642\u0627\u0644: \u0623\u0648\u0644\u064a\u0633\u0648\u0627 \u0628\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u061f \u0642\u0627\u0644 \u0628\u0644\u0649\u060c \u0642\u0627\u0644: \u0641\u0639\u0644\u0627\u0645 \u0646\u0639\u0637\u064a \u0627\u0644\u062f\u0646\u064a\u0629 \u0641\u064a \u062f\u064a\u0646\u0646\u0627\u061f \u0641\u0642\u0627\u0644 \u0623\u0628\u0648 \u0628\u0643\u0631 \u2013 \u0646\u0627\u0635\u062d\u0627\u064b \u0627\u0644\u0641\u0627\u0631\u0648\u0642 \u0628\u0623\u0646 \u064a\u062a\u0631\u0643 \u0627\u0644\u0627\u062d\u062a\u062c\u0627\u062c \u0648\u0627\u0644\u0645\u0639\u0627\u0631\u0636\u0629 - \u0625\u0644\u0632\u0645 \u063a\u0631\u0632\u0647\u060c \u0641\u0625\u0646\u064a \u0623\u0634\u0647\u062f \u0623\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u0627\u0644\u062d\u0642 \u0645\u0627 \u0623\u0645\u0631 \u0628\u0647 \u0648\u0644\u0646 \u0646\u062e\u0627\u0644\u0641 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0644\u0646 \u064a\u0636\u064a\u0651\u0639\u0647 \u0627\u0644\u0644\u0647.",null)
