B.aIN=new A.a("\u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0628\u062a\u0633\u0645 \u0644\u0644\u0630\u064a \u064a\u062c\u0631\u064a \u0628\u064a\u0646 \u0639\u0631\u0648\u0629 \u0627\u0644\u0645\u0634\u0631\u0643 \u0648\u0628\u064a\u0646 \u0627\u0628\u0646 \u0623\u062e\u064a\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u060c \u0648\u0644\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629 \u064a\u0642\u0641 \u0628\u0644\u0628\u0627\u0633\u0647 \u0627\u0644\u062d\u0631\u0628\u064a \u0645\u062a\u0648\u0634\u062d\u0627\u064b \u0628\u0633\u064a\u0641\u0647 \u0648\u062f\u0631\u0639\u0647 \u0648\u0639\u0644\u0649 \u0648\u062c\u0647\u0647 \u0627\u0644\u0645\u063a\u0641\u0631\u060c \u0641\u0625\u0646 \u0639\u0645\u0647 \u0639\u0631\u0648\u0629 \u0644\u0645 \u064a\u0643\u0646 \u0628\u0627\u0633\u062a\u0637\u0627\u0639\u062a\u0647 \u0645\u0639\u0631\u0641\u062a\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0644\u0646\u0628\u064a \ufdfa \u0648\u0647\u0648 \u0641\u064a \u0623\u0634\u062f \u0627\u0644\u063a\u0636\u0628: \u0644\u064a\u062a \u0634\u0639\u0631\u064a \u0645\u0646 \u0623\u0646\u062a \u064a\u0627\u0645\u062d\u0645\u062f \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0623\u0631\u0649 \u0645\u0646 \u0628\u064a\u0646 \u0623\u0635\u062d\u0627\u0628\u0643\u061f \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0647\u0630\u0627 \u0627\u0628\u0646 \u0623\u062e\u064a\u0643 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0628\u0646 \u0634\u0639\u0628\u0629\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0639\u0645\u0647: \u0648\u0623\u0646\u062a \u0628\u0630\u0644\u0643 \u064a\u0627\u063a\u062f\u0631\u061f \u0644\u0642\u062f \u0623\u0648\u0631\u062b\u062a\u0646\u0627 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0645\u0646 \u062b\u0642\u064a\u0641 \u0623\u0628\u062f \u0627\u0644\u062f\u0647\u0631\u060c \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u063a\u0633\u0644\u062a \u063a\u062f\u0631\u062a\u0643 \u0625\u0644\u0627 \u0628\u0627\u0644\u0623\u0645\u0633 \u0643\u0627\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0635\u062d\u0628 \u0642\u0648\u0645\u0627\u064b \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0641\u0642\u062a\u0644\u0647\u0645 \u0648\u0623\u062e\u0630 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u062b\u0645 \u062c\u0627\u0621 \u0641\u0623\u0633\u0644\u0645 \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0623\u0645\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0623\u0642\u0628\u0644 \u0648\u0623\u0645\u0627 \u0627\u0644\u0645\u0627\u0644 \u0641\u0644\u0633\u062a \u0645\u0646\u0647 \u0641\u064a \u0634\u064a\u0621.",null)
