B.aRN=new A.a("\u0627\u0644\u062a\u064a\u0645\u0645 \u064a\u0642\u0648\u0645 \u0645\u0642\u0627\u0645 \u0627\u0644\u063a\u0633\u0644 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u062c\u0646\u0628 \u0645\u0639 \u0648\u062c\u0648\u062f \u0627\u0644\u0645\u0627\u0621 \u0627\u0630\u0627 \u062e\u0634\u064a \u0623\u0646 \u064a\u0624\u062f\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0645\u0627\u0621 \u0627\u0644\u0649 \u0627\u0644\u0636\u0631\u0631\u060c \u0641\u0644\u0642\u062f \u062a\u064a\u0645\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0644\u0645\u0627 \u0623\u0635\u0628\u062d \u062c\u0646\u0628\u0627\u064b \u0645\u0639 \u0648\u062c\u0648\u062f \u0627\u0644\u0645\u0627\u0621 \u0639\u0646\u062f\u0647 \u0648\u0635\u0644\u0649 \u0648\u0623\u0642\u0631\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0644\u0645 \u064a\u0646\u0643\u0631 \u0639\u0644\u064a\u0647.",null)
B.aIW=new A.a("\u064a\u062c\u0648\u0632 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f \u0641\u064a \u0639\u0647\u062f\u0647 \ufdfa : \u0641\u0642\u062f \u0627\u062c\u062a\u0647\u062f \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0641\u062a\u0648\u0636\u0623 \u0648\u0627\u063a\u062a\u0633\u0644 \u0648\u0635\u0644\u0649 \u0648\u0642\u062f \u0627\u062d\u062a\u0644\u0645 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0644\u064a\u0644\u0629 \u0627\u0644\u0628\u0627\u0631\u062f\u0629 \u0627\u0639\u062a\u0645\u0627\u062f\u0627\u064b \u0639\u0644\u0649 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0648\u064e\u0644\u0627 \u062a\u064e\u0642\u0652\u062a\u064f\u0644\u064f\u0648\u0627 \u0623\u064e\u0646\u0652\u0641\u064f\u0633\u064e\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u0643\u064f\u0645\u0652 \u0631\u064e\u062d\u0650\u064a\u0645\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0633\u0627\u0621 \u060c \u0641\u0644\u0645 \u064a\u0646\u0643\u0631 \u0639\u0644\u064a\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0627\u062c\u062a\u0647\u0627\u062f\u0647 \u0628\u0644 \u0623\u0642\u0631\u0647 \u0639\u0644\u0649 \u0623\u0645\u0631\u064a\u0646: \u0627\u0644\u0623\u0648\u0644: \u062c\u0648\u0627\u0632 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u062a\u0635\u062d\u064a\u062d \u0627\u062c\u062a\u0647\u0627\u062f\u0647.",null)
