B.aFJ=new A.a("\u0642\u0627\u0644 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631: \u0644\u0645\u0627 \u0627\u0646\u0647\u0632\u0645 \u0645\u0646 \u0627\u0646\u0647\u0632\u0645 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u064a\u0648\u0645 \u0623\u062d\u062f \u0648\u0642\u062a\u0644 \u0645\u0646 \u0642\u062a\u0644 \u0645\u0646\u0647\u0645\u060c \u0646\u0627\u062f\u0649 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0623\u0644\u0627 \u0625\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0642\u062f \u0642\u062a\u0644 \u0648\u0631\u062c\u0639 \u0627\u0628\u0646 \u0642\u0645\u064a\u0626\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0642\u0627\u0644 \u0644\u0647\u0645: \u0642\u062a\u0644\u062a \u0645\u062d\u0645\u062f\u0627\u064b \u0648\u0625\u0646\u0645\u0627 \u0643\u0627\u0646 \u0642\u062f \u0636\u0631\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0634\u062c\u0647 \u0641\u064a \u0631\u0623\u0633\u0647\u060c \u0641\u0648\u0642\u0639 \u0630\u0644\u0643 \u0641\u064a \u0642\u0644\u0648\u0628 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0648\u0627\u0639\u062a\u0642\u062f\u0648\u0627 \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u0642\u062a\u0644 \u0648\u062c\u0648\u0632\u0648\u0627 \u0639\u0644\u064a\u0647 \u0630\u0644\u0643\u060c \u0643\u0645\u0627 \u0642\u062f \u0642\u0635 \u0627\u0644\u0644\u0647 \u0639\u0646 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u062d\u0635\u0644 \u0636\u0639\u0641 \u0648\u0648\u0647\u0646 \u0648\u062a\u0623\u062e\u0631 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0641\u0641\u064a \u0630\u0644\u0643 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647: \u0648\u064e\u0645\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u0651\u064e\u062f\u064c \u0625\u0650\u0644\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064c \u0642\u064e\u062f\u0652 \u062e\u064e\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0647\u0650 \u0627\u0644\u0631\u0651\u064f\u0633\u064f\u0644\u064f \u0623\u064e\u0641\u064e\u0625\u0650\u0646\u0652 \u0645\u064e\u0627\u062a\u064e \u0623\u064e\u0648\u0652 \u0642\u064f\u062a\u0650\u0644\u064e \u0627\u0646\u0652\u0642\u064e\u0644\u064e\u0628\u0652\u062a\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0639\u0652\u0642\u064e\u0627\u0628\u0650\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0642\u064e\u0644\u0650\u0628\u0652 \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0642\u0650\u0628\u064e\u064a\u0652\u0647\u0650 \u0641\u064e\u0644\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0648\u064e\u0633\u064e\u064a\u064e\u062c\u0652\u0632\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0627\u0644\u0634\u0651\u064e\u0627\u0643\u0650\u0631\u0650\u064a\u0646\u064e - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646 \u060c\u0623\u064a \u0644\u0647 \u0623\u0633\u0648\u0629 \u0628\u0647\u0645 \u0641\u064a \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0641\u064a \u062c\u0648\u0627\u0632 \u0627\u0644\u0642\u062a\u0644 \u0639\u0644\u064a\u0647 \u0648 \u0625\u0646 \u0627\u0644\u0631\u0633\u0644 \u0644\u064a\u0633\u062a \u0628\u0627\u0642\u064a\u0629 \u0641\u064a \u0623\u0642\u0648\u0627\u0645\u0647\u0627 \u0623\u0628\u062f\u0627\u064b \u0641\u0643\u0644 \u0646\u0641\u0633 \u0630\u0627\u0626\u0642\u0629 \u0627\u0644\u0645\u0648\u062a.",null)
B.aV4=new A.a("\u0644\u0642\u062f \u0643\u0627\u0646 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0628\u0644\u0627\u0621 \u0648\u0627\u0644\u0645\u0635\u0627\u0626\u0628 \u0627\u0644\u062a\u064a \u062d\u062f\u062b\u062a \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u064a\u0648\u0645 \u0623\u062d\u062f\u060c \u0623\u0646\u0647\u0645 \u0631\u0628\u0637\u0648\u0627 \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0648\u0639\u0642\u064a\u062f\u062a\u0647\u0645 \u0648\u062f\u0639\u0648\u062a\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u062a\u0647 \u0628\u0634\u062e\u0635 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0641\u0647\u0630\u0627 \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0639\u0642\u064a\u062f\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0627\u064b \u0645\u0639\u0628\u0648\u062f\u0627\u064b \u0648\u062d\u062f\u0647 \u0648\u0628\u064a\u0646 \u0628\u0642\u0627\u0621 \u0634\u062e\u0635 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062e\u0627\u0644\u062f \u0641\u064a\u0647\u0645\u060c \u062e\u0627\u0644\u0637\u0647 \u0627\u0644\u062d\u0628 \u0627\u0644\u0645\u063a\u0644\u0648\u0628 \u0628\u0627\u0644\u0639\u0627\u0637\u0641\u0629 \u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u062e\u0627\u0644\u062f\u0629 \u0648\u0628\u064a\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0627\u0644\u0628\u0634\u0631 \u0627\u0644\u0630\u064a \u064a\u0644\u062d\u0642\u0647 \u0627\u0644\u0645\u0648\u062a\u060c \u0643\u0627\u0646 \u0645\u0646 \u0623\u0633\u0628\u0627\u0628 \u0645\u0627 \u0646\u0627\u0644 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u0641\u0648\u0636\u0649 \u0648\u0627\u0644\u062f\u0647\u0634\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u063a\u0631\u0627\u0628\u060c \u0648\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0623\u0633\u0627\u0633 \u0648\u062c\u0648\u0628 \u0627\u0644\u062a\u0623\u0633\u064a \u0628\u0647 \u0641\u064a \u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u0643\u0627\u0631\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062f\u0627\u0626\u0628 \u0639\u0644\u0649 \u0646\u0634\u0631 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u062a\u0628\u0644\u064a\u063a \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0646\u0635\u0631\u0629 \u0627\u0644\u062d\u0642.",null)
